import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { issueList } from '../../interfaces/issue.interface';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class IssueService {

  constructor(private http: HttpClient) { }


  async fetchIssueList(nCaseid: string): Promise<issueList[]> {
    const params = new HttpParams().set('nCaseid', nCaseid);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<issueList[]>(
          `${environment.cloudUrl}${environment.coreservice}/common/getissuelist`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

}
